window.ENG_PHRASE_DAYS = [{"day": 1, "phrases": [{"ex": "We should take advantage of every chance to practice English.", "exZh": "我们应该利用每一个机会练习英语。", "meaning": "利用", "p": "take advantage of"}, {"ex": "I look forward to hearing from you soon.", "exZh": "我期待很快收到你的来信。", "meaning": "期待", "p": "look forward to"}, {"ex": "Never give up when you meet difficulties.", "exZh": "遇到困难时，永远不要放弃。", "meaning": "放弃", "p": "give up"}, {"ex": "We had to put off the meeting until next week.", "exZh": "我们不得不把会议推迟到下周。", "meaning": "推迟", "p": "put off"}, {"ex": "Women make up half of the students in our class.", "exZh": "女生占我们班学生的一半。", "meaning": "组成；编造；弥补", "p": "make up"}, {"ex": "Many students take part in sports activities after school.", "exZh": "许多学生放学后参加体育活动。", "meaning": "参加", "p": "take part in"}, {"ex": "She gets along well with her classmates.", "exZh": "她和同学们相处得很好。", "meaning": "与……相处", "p": "get along with"}, {"ex": "If you don't know the word, look it up in the dictionary.", "exZh": "如果你不认识这个词，就查字典。", "meaning": "查阅", "p": "look up"}, {"ex": "He turned down the job offer because the pay was too low.", "exZh": "他拒绝了这份工作，因为工资太低了。", "meaning": "拒绝；调低", "p": "turn down"}, {"ex": "Children pick up a foreign language very quickly.", "exZh": "孩子们学外语非常快。", "meaning": "捡起；学会；接", "p": "pick up"}], "title": "动词词组"}, {"day": 2, "phrases": [{"ex": "We have run out of paper, so we need to buy some more.", "exZh": "我们的纸用完了，所以需要再买一些。", "meaning": "用完", "p": "run out of"}, {"ex": "The school set up a new library last year.", "exZh": "学校去年建立了一个新图书馆。", "meaning": "建立", "p": "set up"}, {"ex": "Please go through the report before the meeting.", "exZh": "请在会议前仔细检查这份报告。", "meaning": "经历；仔细检查", "p": "go through"}, {"ex": "Can you come up with a better idea?", "exZh": "你能想出一个更好的主意吗？", "meaning": "提出；想出", "p": "come up with"}, {"ex": "The police are looking into the accident.", "exZh": "警方正在调查这起事故。", "meaning": "调查", "p": "look into"}, {"ex": "New technology has brought about great changes in our life.", "exZh": "新技术给我们的生活带来了巨大变化。", "meaning": "引起；导致", "p": "bring about"}, {"ex": "The workers are carrying out the plan step by step.", "exZh": "工人们正在一步一步地执行这个计划。", "meaning": "执行；实施", "p": "carry out"}, {"ex": "The new manager will take over the company next month.", "exZh": "新经理将于下个月接管这家公司。", "meaning": "接管", "p": "take over"}, {"ex": "Our car broke down on the way to school.", "exZh": "我们的车在去学校的路上抛锚了。", "meaning": "崩溃；分解；出故障", "p": "break down"}, {"ex": "We must learn how to deal with problems calmly.", "exZh": "我们必须学会冷静地处理问题。", "meaning": "处理", "p": "deal with"}], "title": "动词词组"}, {"day": 3, "phrases": [{"ex": "What he said makes a lot of sense.", "exZh": "他说的话很有道理。", "meaning": "有道理；讲得通", "p": "make sense"}, {"ex": "I can't put up with the noise any longer.", "exZh": "我再也忍受不了这种噪音了。", "meaning": "忍受", "p": "put up with"}, {"ex": "You should work hard to keep up with your classmates.", "exZh": "你应该努力学习，跟上同学们的进度。", "meaning": "跟上", "p": "keep up with"}, {"ex": "We should cut down the cost of production.", "exZh": "我们应该削减生产成本。", "meaning": "削减", "p": "cut down"}, {"ex": "We should get rid of bad habits.", "exZh": "我们应该改掉坏习惯。", "meaning": "摆脱；去除", "p": "get rid of"}, {"ex": "She takes good care of her younger brother.", "exZh": "她把弟弟照顾得很好。", "meaning": "照顾", "p": "take care of"}, {"ex": "I finally worked out the difficult math problem.", "exZh": "我终于算出了这道数学难题。", "meaning": "解决；算出；锻炼", "p": "work out"}, {"ex": "The teacher pointed out my mistakes in the essay.", "exZh": "老师指出了我作文中的错误。", "meaning": "指出", "p": "point out"}, {"ex": "Carelessness may result in serious mistakes.", "exZh": "粗心可能导致严重的错误。", "meaning": "导致", "p": "result in"}, {"ex": "Hard work can lead to success.", "exZh": "努力工作可以通向成功。", "meaning": "导致", "p": "lead to"}], "title": "动词词组"}, {"day": 4, "phrases": [{"ex": "He studied hard to catch up with the others.", "exZh": "他努力学习以赶上其他人。", "meaning": "赶上", "p": "catch up with"}, {"ex": "Success depends on hard work and good luck.", "exZh": "成功取决于努力和好运。", "meaning": "依靠；取决于", "p": "depend on"}, {"ex": "You should stick to your plan and never give up.", "exZh": "你应该坚持自己的计划，永不放弃。", "meaning": "坚持", "p": "stick to"}, {"ex": "This book belongs to our teacher.", "exZh": "这本书属于我们老师。", "meaning": "属于", "p": "belong to"}, {"ex": "Please focus on your study and don't waste time.", "exZh": "请专注于学习，不要浪费时间。", "meaning": "专注于", "p": "focus on"}, {"ex": "She wants to apply for a scholarship next year.", "exZh": "她想明年申请奖学金。", "meaning": "申请", "p": "apply for"}, {"ex": "Please refer to the dictionary when you read the text.", "exZh": "读课文时请查阅字典。", "meaning": "提到；参考", "p": "refer to"}, {"ex": "I agree with you on this point.", "exZh": "在这一点上我同意你的看法。", "meaning": "同意", "p": "agree with"}, {"ex": "He apologized for being late for class.", "exZh": "他为上课迟到而道歉。", "meaning": "为……道歉", "p": "apologize for"}, {"ex": "She insisted on finishing the work by herself.", "exZh": "她坚持自己完成这项工作。", "meaning": "坚持", "p": "insist on"}], "title": "动词词组"}, {"day": 5, "phrases": [{"ex": "In other words, we need more time to finish the work.", "exZh": "换句话说，我们需要更多时间来完成这项工作。", "meaning": "换句话说", "p": "in other words"}, {"ex": "In fact, he is one of the best students in our class.", "exZh": "事实上，他是我们班最好的学生之一。", "meaning": "事实上", "p": "in fact"}, {"ex": "He worked hard, and as a result, he passed the exam.", "exZh": "他努力学习，结果通过了考试。", "meaning": "结果", "p": "as a result"}, {"ex": "In addition, we need to buy some vegetables.", "exZh": "此外，我们还需要买一些蔬菜。", "meaning": "此外", "p": "in addition"}, {"ex": "Many countries, for example China, are developing rapidly.", "exZh": "许多国家，例如中国，正在迅速发展。", "meaning": "例如", "p": "for example"}, {"ex": "On the other hand, we should also think about the cost.", "exZh": "另一方面，我们也应该考虑成本。", "meaning": "另一方面", "p": "on the other hand"}, {"ex": "In general, the weather here is warm and wet.", "exZh": "总的来说，这里的天气温暖潮湿。", "meaning": "总的来说", "p": "in general"}, {"ex": "In the end, they found the lost child.", "exZh": "最后，他们找到了走失的孩子。", "meaning": "最后", "p": "in the end"}, {"ex": "We should study hard and at the same time keep healthy.", "exZh": "我们应该努力学习，同时保持健康。", "meaning": "同时", "p": "at the same time"}, {"ex": "In a word, we must work together to solve the problem.", "exZh": "总之，我们必须共同努力解决问题。", "meaning": "总之", "p": "in a word"}], "title": "固定搭配"}, {"day": 6, "phrases": [{"ex": "As soon as he arrived, the meeting began.", "exZh": "他一到，会议就开始了。", "meaning": "一……就", "p": "as soon as"}, {"ex": "He speaks English as well as French.", "exZh": "他既会说英语，也会说法语。", "meaning": "和；也", "p": "as well as"}, {"ex": "As a matter of fact, I have never been to Beijing.", "exZh": "事实上，我从来没有去过北京。", "meaning": "事实上", "p": "as a matter of fact"}, {"ex": "In my opinion, reading is the best way to learn.", "exZh": "在我看来，阅读是最好的学习方法。", "meaning": "在我看来", "p": "in my opinion"}, {"ex": "He is good at English, and in other respects he is also excellent.", "exZh": "他英语很好，在其他方面也很出色。", "meaning": "在其他方面", "p": "in other respects"}, {"ex": "By the way, have you finished your homework?", "exZh": "顺便问一下，你完成作业了吗？", "meaning": "顺便说一下", "p": "by the way"}, {"ex": "In the first place, we should protect the environment.", "exZh": "首先，我们应该保护环境。", "meaning": "首先", "p": "in the first place"}, {"ex": "He got up early in order to catch the first bus.", "exZh": "他起得很早，为的是赶上第一班公共汽车。", "meaning": "为了", "p": "in order to"}, {"ex": "We speak slowly so that everyone can understand us.", "exZh": "我们说得很慢，以便大家都能听懂。", "meaning": "以便", "p": "so that"}, {"ex": "He prefers to walk rather than take a bus.", "exZh": "他宁愿步行也不愿坐公共汽车。", "meaning": "而不是", "p": "rather than"}], "title": "固定搭配"}, {"day": 7, "phrases": [{"ex": "He spent a great deal of time on his homework.", "exZh": "他在作业上花了大量时间。", "meaning": "大量", "p": "a great deal of"}, {"ex": "A number of students took part in the activity.", "exZh": "许多学生参加了这项活动。", "meaning": "许多", "p": "a number of"}, {"ex": "The number of students in our school is over 3,000.", "exZh": "我们学校的学生人数超过3000人。", "meaning": "……的数量", "p": "the number of"}, {"ex": "There are a lot of books in the library.", "exZh": "图书馆里有大量的书。", "meaning": "大量", "p": "a lot of"}, {"ex": "More and more people are learning English now.", "exZh": "现在越来越多的人在学英语。", "meaning": "越来越多", "p": "more and more"}, {"ex": "He visits his grandparents from time to time.", "exZh": "他有时去看望他的祖父母。", "meaning": "有时", "p": "from time to time"}, {"ex": "At present, he is working in a big company.", "exZh": "目前，他在一家大公司工作。", "meaning": "目前", "p": "at present"}, {"ex": "In recent years, our city has changed a lot.", "exZh": "近年来，我们的城市发生了很大变化。", "meaning": "近年来", "p": "in recent years"}, {"ex": "In the future, I want to be a teacher.", "exZh": "将来，我想当一名教师。", "meaning": "在将来", "p": "in the future"}, {"ex": "At first, I didn't like English, but now I love it.", "exZh": "起初，我不喜欢英语，但现在我喜欢它了。", "meaning": "起初", "p": "at first"}], "title": "固定搭配"}, {"day": 8, "phrases": [{"ex": "With the help of the teacher, I finished the task.", "exZh": "在老师的帮助下，我完成了这项任务。", "meaning": "在……的帮助下", "p": "with the help of"}, {"ex": "With the development of science, our life is getting better.", "exZh": "随着科学的发展，我们的生活越来越好。", "meaning": "随着……的发展", "p": "with the development of"}, {"ex": "We should stay calm in the face of danger.", "exZh": "面对危险，我们应该保持冷静。", "meaning": "面对", "p": "in the face of"}, {"ex": "As far as I know, he is a kind man.", "exZh": "据我所知，他是一个善良的人。", "meaning": "据我所知", "p": "as far as I know"}, {"ex": "Thanks to your help, I passed the exam.", "exZh": "多亏你的帮助，我通过了考试。", "meaning": "由于；多亏", "p": "thanks to"}, {"ex": "According to the report, the price will go up.", "exZh": "根据这份报告，价格将会上涨。", "meaning": "根据", "p": "according to"}, {"ex": "I drink water instead of cola.", "exZh": "我喝水而不是可乐。", "meaning": "而不是", "p": "instead of"}, {"ex": "In spite of the rain, they went on working.", "exZh": "尽管下着雨，他们仍继续工作。", "meaning": "尽管", "p": "in spite of"}, {"ex": "He was late because of the heavy traffic.", "exZh": "他因为交通拥堵而迟到了。", "meaning": "因为", "p": "because of"}, {"ex": "In terms of money, he is not rich, but he is happy.", "exZh": "就金钱而言，他并不富有，但他很快乐。", "meaning": "就……而言", "p": "in terms of"}], "title": "固定搭配"}, {"day": 9, "phrases": [{"ex": "Mr. Li is in charge of our class.", "exZh": "李老师负责我们班。", "meaning": "负责", "p": "in charge of"}, {"ex": "Most students are in favor of the new rule.", "exZh": "大多数学生赞成这条新规定。", "meaning": "赞成", "p": "in favor of"}, {"ex": "The children in poor areas are in need of help.", "exZh": "贫困地区的孩子们需要帮助。", "meaning": "需要", "p": "in need of"}, {"ex": "There is a big tree in front of our house.", "exZh": "我们家前面有一棵大树。", "meaning": "在……前面", "p": "in front of"}, {"ex": "Take an umbrella with you in case of rain.", "exZh": "带上雨伞，以防下雨。", "meaning": "万一", "p": "in case of"}, {"ex": "In comparison with last year, our sales have increased.", "exZh": "与去年相比，我们的销售额有所增加。", "meaning": "与……相比", "p": "in comparison with"}, {"ex": "On behalf of our class, I thank you very much.", "exZh": "我代表我们班，非常感谢你。", "meaning": "代表", "p": "on behalf of"}, {"ex": "He stopped in the middle of his speech.", "exZh": "他在演讲中途停了下来。", "meaning": "在……中间", "p": "in the middle of"}, {"ex": "At the end of the term, we will have a test.", "exZh": "学期末，我们将有一场考试。", "meaning": "在……末尾", "p": "at the end of"}, {"ex": "The report is written in the form of a story.", "exZh": "这份报告是以故事的形式写成的。", "meaning": "以……的形式", "p": "in the form of"}], "title": "介词与写作常用词组"}, {"day": 10, "phrases": [{"ex": "He went abroad for the purpose of studying English.", "exZh": "他出国是为了学习英语。", "meaning": "为了", "p": "for the purpose of"}, {"ex": "The city is in the process of building a new subway.", "exZh": "这座城市正在建设新地铁的过程中。", "meaning": "在……过程中", "p": "in the process of"}, {"ex": "He wrote to me in the hope of getting help.", "exZh": "他写信给我，希望得到帮助。", "meaning": "希望", "p": "in the hope of"}, {"ex": "In the event of fire, please stay calm.", "exZh": "如果发生火灾，请保持冷静。", "meaning": "如果发生", "p": "in the event of"}, {"ex": "Under the influence of his teacher, he became a writer.", "exZh": "在老师的影响下，他成为了一名作家。", "meaning": "在……影响下", "p": "under the influence of"}, {"ex": "We made the plan on the basis of the survey.", "exZh": "我们根据调查结果制定了这个计划。", "meaning": "在……基础上", "p": "on the basis of"}, {"ex": "His idea is in line with the law.", "exZh": "他的想法符合法律。", "meaning": "与……一致", "p": "in line with"}, {"ex": "In contrast to his brother, he is very quiet.", "exZh": "与他哥哥形成对比的是，他非常安静。", "meaning": "与……形成对比", "p": "in contrast to"}, {"ex": "In response to your letter, I am writing to say thank you.", "exZh": "作为对你来信的回应，我写信向你表示感谢。", "meaning": "作为对……的回应", "p": "in response to"}, {"ex": "He asked me some questions in relation to my job.", "exZh": "他问了我一些关于我工作的问题。", "meaning": "关于", "p": "in relation to"}], "title": "介词与写作常用词组"}, {"day": 11, "phrases": [{"ex": "First of all, I would like to thank you for your help.", "exZh": "首先，我要感谢你的帮助。", "meaning": "首先", "p": "first of all"}, {"ex": "To sum up, we should work hard and help each other.", "exZh": "总而言之，我们应该努力学习、互相帮助。", "meaning": "总而言之", "p": "to sum up"}, {"ex": "Last but not least, I want to thank my parents.", "exZh": "最后但同样重要的是，我要感谢我的父母。", "meaning": "最后但同样重要的是", "p": "last but not least"}, {"ex": "In short, health is more important than wealth.", "exZh": "简而言之，健康比财富更重要。", "meaning": "简而言之", "p": "in short"}, {"ex": "In summary, learning English takes time and practice.", "exZh": "总之，学习英语需要时间和练习。", "meaning": "总之", "p": "in summary"}, {"ex": "Above all, we must be honest.", "exZh": "最重要的是，我们必须诚实。", "meaning": "首先；最重要的是", "p": "above all"}, {"ex": "After all, he is only a child.", "exZh": "毕竟，他还只是个孩子。", "meaning": "毕竟", "p": "after all"}, {"ex": "At last, we arrived at the top of the mountain.", "exZh": "终于，我们到达了山顶。", "meaning": "终于", "p": "at last"}, {"ex": "In reality, learning a language is not easy.", "exZh": "实际上，学习一门语言并不容易。", "meaning": "实际上", "p": "in reality"}, {"ex": "Generally speaking, girls are more careful than boys.", "exZh": "一般来说，女孩比男孩更细心。", "meaning": "一般来说", "p": "generally speaking"}], "title": "介词与写作常用词组"}, {"day": 12, "phrases": [{"ex": "To a certain extent, I agree with you.", "exZh": "在某种程度上，我同意你的看法。", "meaning": "在某种程度上", "p": "to a certain extent"}, {"ex": "To be honest, I don't like this movie.", "exZh": "老实说，我不喜欢这部电影。", "meaning": "老实说", "p": "to be honest"}, {"ex": "As far as I'm concerned, study comes first.", "exZh": "就我而言，学习是第一位的。", "meaning": "就我而言", "p": "as far as I'm concerned"}, {"ex": "It is widely believed that reading is good for us.", "exZh": "人们普遍认为阅读对我们有好处。", "meaning": "人们普遍认为", "p": "it is widely believed that"}, {"ex": "It is well known that China has a long history.", "exZh": "众所周知，中国有着悠久的历史。", "meaning": "众所周知", "p": "it is well known that"}, {"ex": "There is no doubt that hard work leads to success.", "exZh": "毫无疑问，努力工作会带来成功。", "meaning": "毫无疑问", "p": "there is no doubt that"}, {"ex": "In my view, we should protect animals.", "exZh": "在我看来，我们应该保护动物。", "meaning": "在我看来", "p": "in my view"}, {"ex": "From my point of view, the plan is workable.", "exZh": "从我的角度看，这个计划是可行的。", "meaning": "从我的角度看", "p": "from my point of view"}, {"ex": "In the long run, reading more books will help you a lot.", "exZh": "从长远来看，多读书对你会有很大帮助。", "meaning": "从长远来看", "p": "in the long run"}, {"ex": "In the short term, we need to save money.", "exZh": "从短期来看，我们需要省钱。", "meaning": "从短期来看", "p": "in the short term"}], "title": "介词与写作常用词组"}];
